import re, subprocess, json
REPO = "/tmp/shurik-workspace-EChg2j"
msgs = json.load(open("/tmp/msgs.json"))
def git(*a):
    return subprocess.run(["git","-C",REPO,*a],capture_output=True,text=True).stdout
files = [f for f in git("ls-tree","-r","--name-only","origin/main").split() if re.match(r"^S\d\d/E\d\d\.md$",f)]
pat = re.compile(r"^\*\*(?P<speaker>[^*]+)\*\* \((?P<ts>[^)]+)\)\s*\n\nSource: (?P<branch>friend/[a-z]+) @ (?P<sha>[0-9a-f]{40})\s*\n\n(?P<text>.*?)(?=\n\*\*|\Z)", re.M|re.S)
entries=[]
for f in files:
    c = git("show", f"origin/main:{f}")
    for m in pat.finditer(c):
        entries.append((f,m.group("speaker"),m.group("ts"),m.group("branch"),m.group("sha"),m.group("text").strip("\n")))
print(f"files={len(files)} entries={len(entries)}")
def utterance(message):
    lines = message.split("\n")
    for i,l in enumerate(lines):
        if l.startswith("Reply-To:"):
            j=i+1
            while j<len(lines) and lines[j].strip()=="": j+=1
            return "\n".join(lines[j:])
    return None
bad=unknown=0
for f,sp,ts,br,sha,text in entries:
    m = msgs.get(sha)
    if m is None:
        unknown+=1; print("UNKNOWN",sha[:12],f); continue
    u=utterance(m)
    if u is None or u.strip("\n")!=text.strip("\n"):
        bad+=1
        if bad<=8:
            print("MISMATCH",f,sha[:12]);print("  file:",repr(text[:200]));print("  cmt :",repr((u or "")[:200]))
print(f"mismatch={bad} unknown={unknown}")
